import { expect, test } from "../../fixtures";

const cases = [
  { field: "name", value: "A" },
  { field: "category", value: "furniture" },
  { field: "contact_email", value: "not-an-email" },
] as const;

test.describe("reject invalid vendor fields", () => {
  for (const { field, value } of cases) {
    test(`rejects ${field} set to ${JSON.stringify(value)}`, { tag: "@VEN-02" }, async ({ apiAs }) => {
      // Arrange: a valid vendor payload, with only the field under test made invalid
      const member = await apiAs("member");
      const payload: Record<string, unknown> = {
        name: `Valid Vendor ${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`,
        category: "software",
        contact_email: "billing@vendor.test",
      };
      payload[field] = value;

      // Act
      const response = await member.post("/api/vendors", { data: payload });
      const body = await response.text();

      // Assert
      expect(response.status(), body).toBe(422);
      const error = (JSON.parse(body) as { error: { code: string; fields: { field: string }[] } }).error;
      expect(error.code, body).toBe("validation_error");
      expect(error.fields.map((f) => f.field), body).toContain(field);
    });
  }
});
